if not target_df.empty:
    target_agg = target_df.groupby(group_cols, dropna=False)["INPUT 계획"].sum().reset_index(name="PLANNED_INPUT")
else:
    target_agg = pd.DataFrame(columns=group_cols + ["PLANNED_INPUT"])

if not production_df.empty:
    production_agg = production_df.groupby(group_cols, dropna=False)["PRODUCTION"].sum().reset_index(name="ACTUAL_INPUT")
else:
    production_agg = pd.DataFrame(columns=group_cols + ["ACTUAL_INPUT"])

if not target_agg.empty or not production_agg.empty:
    result = pd.merge(target_agg, production_agg, on=group_cols, how="outer")
else:
    result = pd.DataFrame(columns=group_cols + ["PLANNED_INPUT", "ACTUAL_INPUT"])

result["PLANNED_INPUT"] = result["PLANNED_INPUT"].fillna(0)
result["ACTUAL_INPUT"] = result["ACTUAL_INPUT"].fillna(0)

planned = result["PLANNED_INPUT"]
actual = result["ACTUAL_INPUT"]
result["ACHIEVEMENT_RATE"] = actual.div(planned).mul(100).where(planned.ne(0), 0).fillna(0)

for col in group_cols:
